Contract ProcessSaleService::enterItem(barcode:Integer,quantity:Integer): Boolean {
          definition:
          i:Item = Item.allInstance()->any(o | o.Barcode = barcode), sale:Sale = self.CurrentSale, newStock:Integer = i.StockNumber + (-quantity)

            precondition:
          self.CurrentSale.oclIsUndefined() = false and self.CurrentSale.IsComplete = false and i.oclIsUndefined() = false and i.StockNumber >= quantity

            postcondition:
          { let saleLine:SalesLineItem in saleLine.oclIsNew() and self.CurrentSale.ContainedSalesLine->includes(saleLine) and saleLine.BelongedSale = sale and saleLine.Quantity = quantity and i.StockNumber = newStock and saleLine.Subamount = i.Price * quantity and ThirdPartyServices.saveSaleLine(saleLine) and result = true }

        }
